    ldr   r0, =\slot
    .irp k, 0, 4, 8, 12
    ldr   r2, [r0, #\k]
    PRINT_HEX r2
    .endr
    .endif
    PUTC  '\n'
    ldr   r7, =USART3_BASE
    POOL
.endm

